// client/src/features/dashboard/attendee/JoinSession.jsx
import React from 'react';
import { useLocation, Link } from 'react-router-dom';
import { Jutsu } from 'react-jutsu';
import '../../../styles/GlobalStyles.css';

const JoinSession = () => {
  // grab the ?link=… from the URL
  const { search } = useLocation();
  const link       = new URLSearchParams(search).get('link');

  // derive a Jitsi roomName (the part after the last “/”)
  const roomName = link ? link.split('/').pop() : '';

  return (
    <div className="container">
      <div className="card">
        <h2>Live Session</h2>

        {link
          ? <Jutsu
              roomName={roomName}
              displayName={'Guest'}                // or pull from your auth
              onMeetingEnd={() => {/* optionally redirect */}}
              loadingComponent={<p>Loading…</p>}
              containerStyles={{ width: '100%', height: '600px' }}
            />
          : <p style={{ color: 'red' }}>No session link provided.</p>
        }

        <Link to="/attendee/dashboard">
          <button className="btn" style={{ marginTop: '1rem' }}>
            Back to Dashboard
          </button>
        </Link>
      </div>
    </div>
  );
};

export default JoinSession;
